{
  "schema_version": 1,
  "skill_id": "product-context-brief",
  "stage": "active",
  "cases": [
    {
      "id": "draft-with-evidence-gaps",
      "prompt": "请根据这些材料写一份可供产品与销售共用的简短产品背景。材料：LumenDesk 当前已上线 CSV 导入和重复记录提醒；团队计划下季度开发 SSO，但尚未承诺日期。一次为期 3 周的内部试点覆盖 8 个团队，其中 6 个团队报告每周约节省 20 分钟。定价尚未决定。客户原话 Q1：‘终于不用逐行找重复项了。’内部想法 I1：‘也许可以主打零配置迁移。’不要查外部资料，也不要保存文件。",
      "input": {
        "kind": "synthetic",
        "text": "合成产品、试点、路线图、客户引语和内部想法。"
      },
      "expected_route": "product-context-brief",
      "must_include": [
        "将 CSV 导入和重复记录提醒表述为当前能力，并将 SSO 表述为计划而非已上线或已承诺",
        "保留试点的 3 周、8 个团队、其中 6 个团队及每周约 20 分钟的范围",
        "将 Q1 保留为有来源的客户原话，将 I1 标明为内部想法而非客户证据",
        "明确价格仍未知，并给出足以供产品与销售共用的紧凑背景"
      ],
      "must_avoid": [
        "把路线图写成已交付功能、承诺或销售事实",
        "编造客户引语、价格、竞品事实或更强的试点结论",
        "声称已经查阅外部资料、保存文件或自动写入工作区"
      ]
    },
    {
      "id": "separate-buying-roles",
      "prompt": "把以下访谈摘记整理成角色与需求摘要：客服助理每天实际使用工单表；运营负责人整理需求并向公司推荐工具；CFO 说‘如果提交预算申请，我可能会复核’，但尚未确认谁最终批准采购。当前替代方案是共享表格加邮件提醒。只根据这些材料，不要猜组织架构或竞品。",
      "input": {
        "kind": "synthetic",
        "text": "合成购买角色与当前替代方案访谈。"
      },
      "expected_route": "product-context-brief",
      "must_include": [
        "区分客服助理是实际用户、运营负责人是推荐者或推动者",
        "把 CFO 仅表述为可能复核预算的人，并明确最终决策者或付款方尚未确认",
        "将共享表格加邮件提醒保留为当前替代方案"
      ],
      "must_avoid": [
        "仅凭 CFO 头衔或条件句断定其是最终决策者、付款方或采购批准人",
        "编造组织关系、预算权限、未给出的需求或竞品能力"
      ]
    },
    {
      "id": "update-bounded-context",
      "prompt": "下面是现有背景，请按更正 C1 只更新 Audience 和 Evidence，返回完整四节；Product 和 Voice 必须逐字不变。更正关系要保留，不要静默删除旧说法。\n\nProduct\nBeacon 把支持邮件整理成待办列表。\n\nAudience\n主要用户：支持经理。\n\nEvidence\nE1（4月访谈）：受访者被记录为支持经理，并说‘我每天先分拣邮箱。’\n\nVoice\n直接、克制，不使用‘革命性’。\n\nC1（5月更正）：E1 的受访者实际职位是支持协调员；引语内容不变。",
      "input": {
        "kind": "synthetic",
        "text": "合成既有四节背景及一条带日期的身份更正。"
      },
      "expected_route": "product-context-brief",
      "must_include": [
        "Audience 更新为支持协调员",
        "Evidence 保留 E1 的历史说法、C1 的更正来源及引语内容不变",
        "返回完整四节且 Product 与 Voice 的正文逐字不变"
      ],
      "must_avoid": [
        "静默删除 E1 或把更正后的身份伪装成 E1 当时原始记录",
        "修改 Product 或 Voice 的正文",
        "因这次内容更正擅自引入或递增文档版本号"
      ]
    },
    {
      "id": "compact-sufficient-context",
      "prompt": "材料已经足够，只给恰好 4 个要点，不要提问：产品 PineQueue 为社区诊所整理候诊回电；实际用户是前台协调员；痛点是来电记录散落在便签和共享收件箱；当前功能会合并同一患者的重复回电请求；一轮 5 家诊所、2 周的试用中，4 家称遗漏回电变少，但没有统一计数。",
      "input": {
        "kind": "synthetic",
        "text": "合成且足够完整的紧凑产品背景。"
      },
      "expected_route": "product-context-brief",
      "must_include": [
        "输出恰好 4 个要点",
        "覆盖产品及实际用户",
        "覆盖痛点及当前功能",
        "保留 5 家诊所、2 周、4 家的试用范围，并说明没有统一计数"
      ],
      "must_avoid": [
        "在材料充足时追加问题、长模板或营销活动方案",
        "把试用反馈外推成全部诊所的量化成效",
        "声称保存、发布或同步了背景"
      ]
    },
    {
      "id": "limited-rollout-is-not-general-availability",
      "prompt": "给销售写一份三条要点的当前产品背景：ArcNote 标准版与企业版都已正式开放 CSV 导入。SSO 正在企业版的10个受邀租户中试用，尚未向其他企业租户开放，也不包含标准版。公开定价尚未确定。销售希望下周演示，但工程没有承诺扩大开放的日期。请直接交稿。",
      "input": {
        "kind": "synthetic"
      },
      "expected_route": "product-context-brief",
      "must_include": [
        "恰好三条要点，写明两套餐已正式开放 CSV 导入",
        "将 SSO 限定为企业版10个受邀租户试用，其他企业租户和标准版不能视为已可用",
        "保留定价未知及扩大开放日期未承诺，销售演示意愿不是承诺"
      ],
      "must_avoid": [
        "把 SSO 写成所有企业版客户可用或已经全面上线",
        "将10个受邀租户理解为全部企业客户数量",
        "把下周演示写成下周上线或扩大开放承诺"
      ]
    },
    {
      "id": "newer-sales-note-does-not-resolve-conflict",
      "prompt": "我有两份冲突材料，请写一小段供销售内部使用的当前背景，不查资料。R1，9月8日正式发布记录：SSO 仍为邀请测试，尚未全面开放。R2，9月9日销售笔记：SSO 已经全面上线，可以直接签单。没有提供新发布记录、权限开放清单或产品负责人的确认。只因为 R2 日期更新，能直接把背景改成全面上线吗？",
      "input": {
        "kind": "synthetic"
      },
      "expected_route": "product-context-brief",
      "must_include": [
        "不能仅凭 R2 日期更新认定全面上线",
        "保留 R1/R2 来源及冲突，当前开放范围需核实，不把冲突伪装成已解决",
        "给出供内部使用的短段落，保持全面开放未确认"
      ],
      "must_avoid": [
        "无条件采信较新笔记并把全面上线当成当前事实",
        "无依据宣称销售撒谎或断言 R1 绝对正确且此后从未更新",
        "声称已查询发布系统、确认权限或批准签单"
      ]
    },
    {
      "id": "current-only-correction-with-conditional-roles",
      "prompt": "请交一份给新同事看的当前背景，只要下面这三行，不要附更正历史、旧数值或版本号。历史关系我已另存。现稿：\n产品：NoteLoop 合并重复工单。\n证据：试用覆盖20个团队，其中12个反馈整理更快，未统一计时。\n购买角色：CFO 最终批准采购。\n\n更正 C2：总样本是15个团队，反馈的12个不变，仍未统一计时；CFO 只是可能复核预算，最终批准人未知。请保留产品行原样。",
      "input": {
        "kind": "synthetic"
      },
      "expected_route": "product-context-brief",
      "must_include": [
        "只输出产品、证据、购买角色三行，并保留产品行原样",
        "证据改为15个团队、其中12个反馈整理更快且未统一计时",
        "CFO 仅可能复核预算，最终批准人未知"
      ],
      "must_avoid": [
        "附加旧数值20、更正历史或版本号",
        "把样本更正后反馈数也改掉或编造成量化提效",
        "保留 CFO 已确定的最终批准权"
      ]
    }
  ]
}

